<https://example.org/openevidence/questions/q_pancreatitis_efficacy> a holon:ClinicalQuestionHolon ;
    oe:questionText "How effective is morphine compared with other agents for Pancreatitis?"^^xsd:string ;
    oe:answerText "Persistent chylomicronemia is a genetic recessive disorder that is classically caused by familial chylomicronemia syndrome (FCS), but it also has multifactorial causes. The disorder is associated with the risk of recurrent acute pancreatitis."^^xsd:string ;
    oe:belongsToSpecialty "Gastroenterology" ;
